</template>

<script setup>
import { computed, ref } from 'vue'
import { expansionAt } from './model.js'

const teacherMode = ref(false)
const scale = ref(0.5)
const state = computed(() => expansionAt(scale.value))
const redshift = computed(() => state.value.redshift)
const observedWavelength = computed(() => state.value.observedWavelengthNm)
const presets = [{ label: 'a = 0.25', value: 0.25 }, { label: 'a = 0.50', value: 0.5 }, { label: 'a = 1.00', value: 1 }]
const chapters = [{ id: 'path', label: '理论路径' }, { id: 'simulator', label: '动手模拟' }, { id: 'evidence', label: '观测证据' }, { id: 'timeline', label: '宇宙年表' }, { id: 'teaching', label: '课堂使用' }]
const theory = [
  { kicker: '物质告诉时空如何弯曲', title: '广义相对论', summary: '场方程连接时空几何与能量、动量；它给出可能的宇宙模型，而不是独自规定宇宙必须静止。', formula: 'Gμν + Λgμν = (8πG/c⁴)Tμν', formulaLabel: '爱因斯坦场方程，含宇宙学常数', detail: '左侧的 Gμν 描述曲率，Tμν 是物质与辐射的能量动量张量，Λ 是宇宙学常数。1917 年爱因斯坦为求静态解引入 Λ；今天它仍是标准宇宙学模型中的重要参数。' },
  { kicker: '先写下宇宙的大尺度对称性', title: 'FLRW 度规', summary: '假设宇宙在足够大尺度上均匀、各向同性，用一个尺度因子 a(t) 描述空间距离随时间变化。', formula: 'ds² = −c²dt² + a²(t)[dr²/(1−kr²) + r²dΩ²]', formulaLabel: '弗里德曼勒梅特罗伯逊沃尔克度规', detail: 'k 描述空间曲率的符号，r 是共动径向坐标。先用对称性建立这类度规，再把它与理想流体形式的物质代入场方程，才得到宇宙的动力学方程。' },
  { kicker: '让尺度因子随物质演化', title: '弗里德曼方程', summary: '它把膨胀率 H、物质和辐射的密度、空间曲率以及宇宙学常数联系起来。', formula: 'H² = (ȧ/a)² = 8πGρ/3 − kc²/a² + Λc²/3', formulaLabel: '第一弗里德曼方程，rho 为质量密度', detail: '这里 ρ 取质量密度单位；若使用能量密度，系数需相应改写。另一个加速度方程涉及压强：ä/a = −4πG(ρ + 3p/c²)/3 + Λc²/3。不同成分使 a(t) 的演化不同。' },
  { kicker: '把模型连到光谱观测', title: '尺度因子与红移', summary: '随空间膨胀传播的光，其波长与 a 同比例拉伸；附近星系的距离与退行率近似成正比。', formula: '1 + z = a₀/aₑ  ·  v ≈ H₀d（近邻）', formulaLabel: '宇宙学红移与近邻哈勃勒梅特定律', detail: '习惯把今天的 a₀ 归一化为 1。H = ȧ/a；H₀ 是今天的值。哈勃—勒梅特定律的 v≈H₀d 用于低红移、哈勃流主导的近邻情形；更远处要使用模型的距离—红移关系。' },
]
const eras = [
  { time: '极早期 · 尚未完全理解', title: '极早期与暴胀假说', detail: '可观测宇宙的早期状态极热极密。暴胀是解释大尺度均匀性和原初扰动的理论框架之一，其具体机制仍在研究。现有模型不能确定“最初一刻”之前发生了什么。', question: '哪些内容是直接观测，哪些是由模型推断？' },
  { time: '最初几分钟', title: '原初核合成', detail: '宇宙冷却到质子、中子能够形成一部分轻元素原子核的条件，留下氢、氦和少量锂的原初比例线索。', question: '为什么元素丰度可以作为热历史的独立证据？' },
  { time: '约 38 万年', title: '中性原子形成与 CMB', detail: '电子与原子核结合后，光子不再频繁被自由电子散射，宇宙逐渐透明。那时释放的光被膨胀拉长，如今以宇宙微波背景的形式被观测。', question: '为什么我们不能用普通光直接看到更早的高温等离子体？' },
  { time: '数亿年后', title: '第一批恒星与星系', detail: '引力使早期密度起伏逐渐长成结构，第一批恒星和星系出现。具体形成时间与过程仍由观测持续约束。', question: '微小的早期起伏怎样变成今天的星系网络？' },
  { time: '约 138 亿年后 · 今天', title: '持续膨胀的宇宙', detail: '星系巡天、超新星与 CMB 等共同约束宇宙模型。当前标准模型包含暗物质和与加速膨胀相关的暗能量描述，但其物理本质仍未解决。', question: '不同证据给出的参数若有张力，科学家该怎样检验？' },
]
const eraIndex = ref(2)
const activeEra = computed(() => eras[eraIndex.value])
function wavePath(cycles) {
  const points = Array.from({ length: 121 }, (_, i) => {
    const x = i * 4.5
    return `${i ? 'L' : 'M'}${x.toFixed(1)},${(45 + 18 * Math.sin((i / 120) * cycles * 2 * Math.PI)).toFixed(1)}`
  })
  return points.join(' ')
}
const emittedWave = wavePath(10)
const receivedWave = computed(() => wavePath(10 * scale.value))
</script>

